// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.core/** * NOUS — ExecuTorch Backend Selection (Module 6 v4 — Step 6.1, CRITICAL). * * Enumerates the 3 compilation backends for the Omni-SLM, per strategy v4 * §"Critical Engineering Fix 1: MediaTek NPU / ExecuTorch Gap". * * ## The 3-Backend Matrix * * v3 blindly assumed QNN delegate worked everywhere. v4 fixes this: * * | Backend | Vendor | When to use | Omni-SLM Latency | * |---------|--------|-------------|------------------| * | QNN | Qualcomm | Snapdragon 7 Gen 1+ with NPU | 350-450 ms ✅ | * | NEUROPILOT | MediaTek | Helio G99 / Dimensity 700+ with NPU | 450-650 ms ✅ | * | XNNPACK | Any (CPU) | Fallback — Helio G85 (no NPU), ultra-low RAM | 800-1200 ms ⚠️ | * | OPENCL | Any (GPU) | Co-fallback with XNNPACK — parallelizable layers | 600-900 ms ⚠️ | * * ## Selection Logic * * [ModelManager] uses [DeviceCapability] to select the correct backend: * * ``` * Qualcomm + NPU + Mid/High RAM  →  QNN * MediaTek + NPU + Mid/High RAM  →  NEUROPILOT (fallback: OPENCL) * MediaTek no NPU + Low RAM      →  XNNPACK (fallback: OPENCL) * Ultra-low RAM (2 GB)          →  Omni-SLM DISABLED (v2 stack fallback) * ``` * * ## Build-time Compilation * * The Omni-SLM is compiled to **3 separate `.pte` files** at NOUS build time: * *  - `omni-slm-int4-qnn.pte`        (580 MB — for Qualcomm devices) *  - `omni-slm-int4-neuropilot.pte` (580 MB — for MediaTek NPU devices) *  - `omni-slm-int4-xnnpack.pte`    (580 MB — for CPU fallback) *  - `omni-slm-int2-xnnpack.pte`    (290 MB — for 3 GB RAM tier, INT2 quantization) * * APK ships all 4 (Play Asset Delivery reduces per-device download by ~580 MB). * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Critical Engineering Fix 1</a> */enum class ExecuTorchBackend(val displayName: String) {    /**     * Qualcomm Neural Network delegate — for Snapdragon 7 Gen 1+ chips with     * Hexagon DSP HVX.     *     * Best latency (350-450 ms) but only works on Qualcomm hardware.     */    QNN("Qualcomm QNN"),    /**     * MediaTek NeuroPilot backend — for Helio G99+ and Dimensity 700+ chips     * with APU (AI Processing Unit).     *     * Compiles Omni-SLM graph to NeuroPilot's APU instruction set.     * Latency: 450-650 ms.     */    NEUROPILOT("MediaTek NeuroPilot"),    /**     * OpenCL GPU backend — co-fallback for parallelizable layers when NPU     * backends are unavailable or fail.     *     * Works on any device with an OpenCL-capable GPU (Mali, Adreno, PowerVR).     * Latency: 600-900 ms.     */    OPENCL("OpenCL GPU"),    /**     * XNNPACK CPU backend — highly optimized for mobile CPUs with ARM NEON     * and FP16 SIMD instructions.     *     * Used as the final fallback when no NPU/GPU acceleration is available     * (e.g., MediaTek Helio G85, Unisoc Tiger).     * Latency: 800-1200 ms (acceptable but not great).     */    XNNPACK("XNNPACK CPU"),    /**     * Disabled — Omni-SLM cannot run on this device (ultra-low RAM tier, < 3 GB).     *     * Falls back to v2 stack: MiniLM-L6 (22 MB) + BERT-tiny (16 MB) + MobileViT-S (80 MB).     * Total: 180 MB RAM. Works on 2 GB devices.     */    DISABLED("Disabled (v2 fallback)"),}// ──────────────────────────────────────────────────────────────────────────/** * Quantization level for the Omni-SLM model. * * Drives memory footprint vs accuracy trade-off. */enum class OmniSlmQuantization(val displayName: String, val estimatedSizeMb: Int) {    /**     * INT4 weights + INT8 activations.     *     * - Size: 580 MB on disk.     * - RAM resident: 720 MB (580 MB weights + 140 MB KV cache).     * - Accuracy: 100% (baseline).     * - Used on: High (6GB+) and Mid (4GB) RAM tiers.     */    INT4("INT4", 580),    /**     * INT2 weights + INT8 activations.     *     * - Size: 290 MB on disk (50% smaller than INT4).     * - RAM resident: 330 MB (290 MB weights + 40 MB KV cache).     * - Accuracy: 88-92% (8-12% accuracy drop vs INT4).     * - Used on: Low (3GB) RAM tier — required for LMK survival.     */    INT2("INT2", 290),}// ──────────────────────────────────────────────────────────────────────────/** * Select the best [ExecuTorchBackend] for the given [DeviceCapability]. * * This is the v4 3-backend matrix implementation. * * @param capability the device's hardware capability snapshot. * @return the selected backend (or [ExecuTorchBackend.DISABLED] if Omni-SLM *         cannot run). */fun selectOmniSlmBackend(capability: DeviceCapability): ExecuTorchBackend {    // Ultra-low RAM (2 GB) — disable Omni-SLM entirely.    if (capability.ramTier == RamTier.ULTRA) {        return ExecuTorchBackend.DISABLED    }    return when (capability.socVendor) {        SocVendor.QUALCOMM -> {            if (capability.hasNpu && capability.ramTier >= RamTier.MID) {                ExecuTorchBackend.QNN            } else {                // Qualcomm without NPU (rare) or low RAM — use XNNPACK.                ExecuTorchBackend.XNNPACK            }        }        SocVendor.MEDIATEK -> {            if (capability.hasNpu && capability.ramTier >= RamTier.MID) {                // MediaTek with NPU — use NeuroPilot, fall back to OpenCL.                ExecuTorchBackend.NEUROPILOT            } else {                // MediaTek without NPU (Helio G85) — use XNNPACK + OpenCL.                ExecuTorchBackend.XNNPACK            }        }        SocVendor.SAMSUNG_EXYNOS -> {            if (capability.hasNpu) {                // Exynos with NPU — use OpenCL (Eden NPU doesn't have a stable                // ExecuTorch delegate yet, fall back to OpenCL).                ExecuTorchBackend.OPENCL            } else {                ExecuTorchBackend.XNNPACK            }        }        SocVendor.GOOGLE_TENSOR -> {            // Tensor has EdgeTPU — but ExecuTorch EdgeTPU delegate is still            // experimental. Fall back to XNNPACK for now (Tensor CPU is fast).            ExecuTorchBackend.XNNPACK        }        SocVendor.UNISOC, SocVendor.OTHER -> {            // Unisoc and unknown vendors — XNNPACK CPU only.            ExecuTorchBackend.XNNPACK        }    }}/** * Select the appropriate [OmniSlmQuantization] for the given [capability]. * * - High/Mid RAM (4 GB+) → INT4 (580 MB) * - Low RAM (3 GB)        → INT2 (290 MB) — required for LMK survival * - Ultra RAM (2 GB)      → Disabled (v2 fallback) */fun selectOmniSlmQuantization(capability: DeviceCapability): OmniSlmQuantization? {    return when (capability.ramTier) {        RamTier.HIGH, RamTier.MID -> OmniSlmQuantization.INT4        RamTier.LOW -> OmniSlmQuantization.INT2        RamTier.ULTRA -> null  // Omni-SLM disabled    }}/** * Compute the model filename for the given backend + quantization. * * Example: `omni-slm-int4-qnn.pte` */fun omniSlmModelFilename(    backend: ExecuTorchBackend,    quantization: OmniSlmQuantization,): String {    val backendSuffix = when (backend) {        ExecuTorchBackend.QNN -> "qnn"        ExecuTorchBackend.NEUROPILOT -> "neuropilot"        ExecuTorchBackend.OPENCL -> "opencl"        ExecuTorchBackend.XNNPACK -> "xnnpack"        ExecuTorchBackend.DISABLED -> return ""  // No file for disabled    }    return "omni-slm-${quantization.name.lowercase()}-$backendSuffix.pte"}// ──────────────────────────────────────────────────────────────────────────/** * Resolve the primary + fallback backend chain for [capability]. * * Returns a list ordered by preference. ModelManager tries each in order * until one successfully loads. * * Example for MediaTek Helio G99 with NPU: *   [NEUROPILOT, OPENCL, XNNPACK] * * Example for MediaTek Helio G85 (no NPU): *   [XNNPACK, OPENCL] * * Example for Qualcomm Snapdragon 8 Gen 3: *   [QNN, XNNPACK] */fun resolveBackendChain(capability: DeviceCapability): List<ExecuTorchBackend> {    if (capability.ramTier == RamTier.ULTRA) {        return listOf(ExecuTorchBackend.DISABLED)    }    val primary = selectOmniSlmBackend(capability)    val chain = mutableListOf<ExecuTorchBackend>()    if (primary != ExecuTorchBackend.DISABLED) {        chain.add(primary)    }    // Add fallbacks (skip if already in chain).    when (primary) {        ExecuTorchBackend.QNN -> {            chain.add(ExecuTorchBackend.XNNPACK)        }        ExecuTorchBackend.NEUROPILOT -> {            chain.add(ExecuTorchBackend.OPENCL)            chain.add(ExecuTorchBackend.XNNPACK)        }        ExecuTorchBackend.OPENCL -> {            chain.add(ExecuTorchBackend.XNNPACK)        }        ExecuTorchBackend.XNNPACK -> {            // XNNPACK is already the last fallback; optionally add OpenCL.            if (!chain.contains(ExecuTorchBackend.OPENCL)) {                chain.add(ExecuTorchBackend.OPENCL)            }        }        ExecuTorchBackend.DISABLED -> {            // No fallbacks — use v2 stack instead.        }    }    return chain.distinct()}